			AtomicInteger closes = new AtomicInteger();
			LmdbPrefixRunPlan plan = mock(LmdbPrefixRunPlan.class);
			when(fixture.delegate.prefixRunPlan(any(int[].class), anyLong(), anyLong(), anyLong(), anyLong()))
					.thenReturn(plan);
