	@Test
	void floatingArithmeticAndFullConcatReplayAllOriginalEvents() throws Exception {
		try (Fixture fixture = new Fixture("number", "text", "result")) {
			List<ValuesRow> rows = List.of(fixture.values(1e16, "a"), fixture.values(1D, "bb"),
					fixture.values(-1e16, "a"), fixture.values(1D, "bb"), fixture.values(1e16, "a"),
					fixture.values(-1e16, "a"));
			AggregateSpec[] aggregates = { AggregateSpec.slot("sum", 0, false, AggKind.SUM),
					AggregateSpec.groupConcat("text", 2, false, "|") };
			NativeTermDomainPlan domain = fixture.domain(rows, length(Var.of("text")), 2, new int[0], aggregates);
			assertThat(domain.collapseWeights).isFalse();
			BindingSet result = fixture.reduce(domain, new int[0], aggregates).getFirst();
			assertThat(((Literal) result.getValue("sum")).doubleValue()).isZero();
			assertThat(result.getValue("text").stringValue()).isEqualTo("1|2|1|2|1|1");
			assertThat(fixture.domainTarget.getLongMetricActual("nativeTermDomainTuplesActual")).isEqualTo(3L);
			assertThat(fixture.evaluations.get()).as("ordered dependency replay still reuses the two scalar inputs")
					.isEqualTo(2);
			assertThat(fixture.outputRows).isEqualTo(6L);
			assertThat(fixture.logicalRows).isEqualTo(6L);
		}
	}

